SET FOREIGN_KEY_CHECKS = 0;
CREATE DATABASE IF NOT EXISTS sistema_educacional;
USE sistema_educacional;

CREATE TABLE MUNICIPIO (
id_municipio NUMERIC(7) PRIMARY KEY,
nome VARCHAR(100) NOT NULL,
sigla_uf CHAR(2) NOT NULL,
nome_uf VARCHAR(20) NOT NULL,
nome_regiao VARCHAR(15) NOT NULL CHECK (nome_regiao IN ('Norte','Nordeste','Centro-Oeste','Sudeste','Sul')),
capital_uf NUMERIC(1) NOT NULL CHECK (capital_uf IN (0,1)),
ddd NUMERIC(2) NOT NULL CHECK (ddd >= 11 AND ddd <= 99),
amazonia_legal NUMERIC(1) NOT NULL CHECK (amazonia_legal IN (0,1)),
id_regiao_metropolitana NUMERIC(5) CHECK (id_regiao_metropolitana > 0),
nome_regiao_metropolitana VARCHAR(100),
id_municipio_6 NUMERIC(7),
id_municipio_tse NUMERIC(7),
id_municipio_rf NUMERIC(7),
id_municipio_bcb NUMERIC(7),
id_comarca INT,
id_regiao_saude INT,
nome_regiao_saude VARCHAR(100),
id_regiao_imediata INT,
nome_regiao_imediata VARCHAR(100),
id_regiao_intermediaria INT,
nome_regiao_intermediaria VARCHAR(100),
id_microrregiao INT,
nome_microrregiao VARCHAR(100),
id_mesorregiao INT,
nome_mesorregiao VARCHAR(100),
id_uf INT,
centroide VARCHAR(100)
);

CREATE TABLE ESCOLA (
id_escola NUMERIC(8) PRIMARY KEY,
id_municipio NUMERIC(7) NOT NULL,
ano NUMERIC(4) NOT NULL CHECK (ano BETWEEN 2020 AND 2023),
rede NUMERIC(1) NOT NULL CHECK (rede IN (1, 2, 3, 4)),
tipo_localizacao NUMERIC(1) NOT NULL CHECK (tipo_localizacao IN (1, 2)),
tipo_situacao_funcionamento NUMERIC(1) NOT NULL CHECK (tipo_situacao_funcionamento BETWEEN 1 AND 4),
data_ano_letivo_inicio DATE,
data_ano_letivo_termino DATE,
quantidade_funcionario NUMERIC(4),
quantidade_matricula_educacao_basica NUMERIC(5),
tipo_categoria_escola_privada INT,
tipo_localizacao_diferenciada INT,
id_orgao_regional INT
);

CREATE TABLE DOCENTE (
id_docente VARCHAR(32) PRIMARY KEY,
id_municipio NUMERIC(7) NOT NULL,
id_escola NUMERIC(8) NOT NULL,
ano NUMERIC(4) NOT NULL CHECK (ano BETWEEN 2020 AND 2023),
sexo NUMERIC(1) NOT NULL CHECK (sexo IN (1, 2)),
idade NUMERIC(3) NOT NULL CHECK (idade BETWEEN 18 AND 100),
raca_cor NUMERIC(1) NOT NULL CHECK (raca_cor BETWEEN 0 AND 5),
escolaridade NUMERIC(1) NOT NULL CHECK (escolaridade BETWEEN 1 AND 8),
tipo_contratacao NUMERIC(1) NULL CHECK (tipo_contratacao BETWEEN 1 AND 9 OR tipo_contratacao IS NULL),
id_turma INT,
etapa_ensino INT,
rede VARCHAR(20) NOT NULL CHECK (rede IN ('municipal', 'estadual', 'federal', 'privada')),
tipo_turma INT,
mes_nascimento_docente INT,
ano_nascimento_docente INT,
dia_nascimento_docente INT,
idade_referencia INT,
nacionalidade INT,
id_pais_origem INT,
id_uf_nascimento INT,
id_municipio_nascimento INT,
id_uf_endereco INT,
id_municipio_endereco INT,
zona_residencial INT,
necessidades_especiais INT,
formacao1 INT,
formacao2 INT,
formacao3 INT,
disciplinas_lecionadas VARCHAR(200)
);

CREATE TABLE TURMA (
id_turma NUMERIC(8) PRIMARY KEY,
id_escola NUMERIC(8) NOT NULL,
id_municipio NUMERIC(7) NOT NULL,
ano NUMERIC(4) NOT NULL CHECK (ano BETWEEN 2020 AND 2023),
etapa_ensino NUMERIC(2) CHECK (etapa_ensino BETWEEN 1 AND 70),
tipo_turma NUMERIC(1) CHECK (tipo_turma BETWEEN 1 AND 5),
quantidade_matriculas NUMERIC(3) NOT NULL CHECK (quantidade_matriculas BETWEEN 0 AND 999),
hora_inicial NUMERIC(2),
minuto_inicial NUMERIC(2),
rede VARCHAR(30),
dias_semana VARCHAR(50),
tipo_atividade NUMERIC(1),
numero_dias_atividade INT,
numero_duracao_turma NUMERIC(4),
disciplinas_oferecidas VARCHAR(200),
recursos_especiais VARCHAR(100),
localizacao VARCHAR(100)
);

CREATE TABLE MATRICULA (
id_matricula NUMERIC(8) PRIMARY KEY,
id_turma NUMERIC(8) NOT NULL,
id_escola NUMERIC(8) NOT NULL,
id_municipio NUMERIC(7) NOT NULL,
ano NUMERIC(4) NOT NULL CHECK (ano BETWEEN 2020 AND 2023),
id_aluno VARCHAR(32) NOT NULL,
idade NUMERIC(3) NOT NULL CHECK (idade BETWEEN 0 AND 150),
sexo NUMERIC(1) NOT NULL CHECK (sexo IN (1, 2)),
raca_cor NUMERIC(1) NOT NULL CHECK (raca_cor BETWEEN 0 AND 5),
etapa_ensino NUMERIC(2) NOT NULL CHECK (etapa_ensino BETWEEN 1 AND 70),
id_distrito INT,
rede INT,
id_pessoa_fisica INT,
dados_nascimento VARCHAR(50),
idade_referencia INT,
nacionalidade INT,
id_pais_origem INT,
id_uf_nascimento INT,
id_municipio_nascimento INT,
id_uf_endereco INT,
id_municipio_endereco INT,
zona_residencial INT,
transporte INT,
necessidades_especiais INT,
recursos_apoio INT
);

ALTER TABLE ESCOLA ADD CONSTRAINT fk_escola_municipio FOREIGN KEY (id_municipio) REFERENCES MUNICIPIO(id_municipio);
ALTER TABLE DOCENTE ADD CONSTRAINT fk_docente_municipio FOREIGN KEY (id_municipio) REFERENCES MUNICIPIO(id_municipio);
ALTER TABLE DOCENTE ADD CONSTRAINT fk_docente_escola FOREIGN KEY (id_escola) REFERENCES ESCOLA(id_escola);
ALTER TABLE TURMA ADD CONSTRAINT fk_turma_escola FOREIGN KEY (id_escola) REFERENCES ESCOLA(id_escola);
ALTER TABLE TURMA ADD CONSTRAINT fk_turma_municipio FOREIGN KEY (id_municipio) REFERENCES MUNICIPIO(id_municipio);
ALTER TABLE MATRICULA ADD CONSTRAINT fk_matricula_turma FOREIGN KEY (id_turma) REFERENCES TURMA(id_turma);
ALTER TABLE MATRICULA ADD CONSTRAINT fk_matricula_escola FOREIGN KEY (id_escola) REFERENCES ESCOLA(id_escola);
ALTER TABLE MATRICULA ADD CONSTRAINT fk_matricula_municipio FOREIGN KEY (id_municipio) REFERENCES MUNICIPIO(id_municipio);


